class UnifyAppsUserSession {
  sessionId: string;
  lastActiveTimestamp: number | null;
  sessionTimeout: number;
  sessionStart: boolean;

  constructor() {
    this.sessionId = window.localStorage.getItem("sessionId") || "";
    this.lastActiveTimestamp = window.localStorage.getItem(
      "lastActiveTimestamp"
    )
      ? parseInt(window.localStorage.getItem("lastActiveTimestamp") as string)
      : 0;
    this.sessionTimeout = window.localStorage.getItem("sessionTimeout")
      ? parseInt(window.localStorage.getItem("sessionTimeout") as string)
      : 0;
    this.sessionStart = false;
  }

  setSessionTimeout(timeout: number) {
    this.sessionTimeout = timeout;
  }

  startSession(sessionId?: string) {
    const currentTimestamp = Date.now();
    this.sessionId = sessionId || Math.floor(currentTimestamp/1000).toString();
    this.sessionStart = true;
    this.lastActiveTimestamp = currentTimestamp;
    window.localStorage.setItem("sessionId", this.sessionId);
    window.localStorage.setItem("lastActiveTimestamp", this.lastActiveTimestamp.toString());
  }

  startSessionIfNeeded() {
    if (!this.lastActiveTimestamp) {
      this.startSession();
      return;
    }
    if (Date.now() - this.lastActiveTimestamp > this.sessionTimeout) {
      this.refreshSession();
    }
  }

  refreshSession() {
    this.clearSession();
    this.startSession();
  }

  isSessionStarted(sessionStart:boolean){
    this.sessionStart = sessionStart;
  }

  clearSession() {
    this.sessionId = "";
    this.lastActiveTimestamp = null;
    this.sessionStart = false;
    window.localStorage.removeItem("sessionId");
    window.localStorage.removeItem("lastActiveTimestamp");
  }

  updateLastActiveTimestamp() {
    this.lastActiveTimestamp = Date.now();
    window.localStorage.setItem("lastActiveTimestamp", this.lastActiveTimestamp.toString());
  }

  getSessionId() {
    return this.sessionId;
  }
}

export default UnifyAppsUserSession;
